    "instructor": "Doç. Dr. RIDVAN YARBA",
    "purpose": "Bu dersin amacı, öğrencilerin klasik hadis kaynaklarını doğrudan okuyup anlayabilecek düzeye gelmelerini, hadis metinlerinin dil, üslup ve terminolojisine aşina olmalarını sağlamaktır. Ayrıca, temel hadis külliyatının yapısını ve rivayet sistematiğini kavramaları, klasik metinlerdeki ilmî tartışmaları analiz edebilmeleri hedeflenmektedir.",
    "content": "Ders kapsamında Kütüb-i Sitte ve diğer klasik hadis kaynaklarından seçilmiş metinler okunur, metinlerdeki dil özellikleri, râvi ifadeleri, sened-metin ilişkisi, yorum farkları ve şerh geleneği incelenir. Öğrenciler klasik hadis metinlerinin ilmî yapısını analiz etmeyi ve eleştirel okuma becerilerini geliştirmeyi öğrenirler.",
    "methods": "- Klasik metin okuma ve analiz- Karşılaştırmalı okuma- Tartışma ve yorumlama- Uygulamalı etkinlikler- Örnek olay incelemesi",
    "resources": "Dersin gerçek OBS kaynakları; birincil ve ikincil temel_islam_bilimleri kaynakları, güncel temel_islam_bilimleri literatürü, arşiv ve kütüphane katalogları ile hakemli makaleler.",
