    "name": "AHKAM AYETLERİ",
    "type": "Seçmeli",
    "credit": 3,
    "ects": 6,
    "theory": 3,
    "practice": 0,
    "term": "Güz",
    "instructor": "Doç. Dr. MUHAMMED ÇUÇAK",
    "purpose": "Bu ders, öğrencilerin Kur’an ve sünnet ışığında İslam hukuku, ibadetler, aile hukuku ve toplumsal düzen konularında derinlemesine bilgi sahibi olmalarını sağlamak; ayrıca Kur’an ayetlerinin tefsir, i‘rab ve uygulama boyutlarını öğrenerek hem teorik hem pratik bir bakış kazandırmayı hedefler. Ders, klasik fıkıh konularını güncel meselelerle ilişkilendirerek öğrencilerin eleştirel düşünme ve çözüm üretme becerilerini geliştirmeyi amaçlar.",
    "content": "Kur’an ayetleri, hadisler ve şer’i hükümler, İbadetler (namaz, oruç, hac-umre) ve hükümlerin detayları• Aile hukuku: nikâh, boşanma, mehir, nafaka, yetim hakları• Hudûd ve cezai hükümler, toplumsal adalet uygulamaları• Güncel meseleler ve toplumsal görgü kuralları• Tefsir, i‘rab, nesih ve sihir gibi klasik kavramlar",
    "methods": "Anlatım ve açıklama: Fakihlerin görüşleri ve Kur’an ayetleri detaylı şekilde açıklanır.• Tartışma ve münazara: Hudûd, aile hukuku ve güncel meselelerde öğrencilerin fikir geliştirmesi sağlanır.• Vaka analizi ve örnekleme: İslami hükümler günlük yaşamdaki durumlara uygulanır.• Tefsir ve i‘rab çalışmaları: Ayetlerin dilbilgisel ve anlam boyutları örneklerle incelenir.• Soru-cevap ve interaktif öğrenme: Öğrencilerin aktif katılımı teşvik edilir.",
    "resources": "Dersin gerçek OBS kaynakları; birincil ve ikincil temel_islam_bilimleri kaynakları, güncel temel_islam_bilimleri literatürü, arşiv ve kütüphane katalogları ile hakemli makaleler.",
    "sdgs": [
      "4",
      "10",
      "16"
    ],
    "outcomes": [
      "Ahkam ayetleri kapsamındaki ileri kuramsal bilgileri analiz eder.",
      "Fıkıh ve İslam hukuku yaklaşımlarını karşılaştırır.",
      "Ahkam ayetleri kapsamında uygun temel_islam_bilimleri araştırma yöntemini uygular.",
      "Ahkam ayetleri bulgularını temel_islam_bilimlerisel ve toplumsal bağlamıyla değerlendirir.",
      "Ahkam ayetleri alanındaki kanıtlara dayalı temel_islam_bilimlerisel argüman geliştirir."
    ],
    "weeklyTopics": [
      "Giriş ve Fatiha Suresi • Kitaba ve müellife genel bakış • Fatihe suresi üzerine: o Fazileti o İstiâze o Tefsir ve i‘rab örnekleri o Besmelenin hükmü ve namazda okunması",
      "Sihir ve Hükümleri • Şeriatın sihre bakışı • Sebeb-i nüzul • İ‘rab yönleri • Sihir hakikat midir? • Sihir öğrenmek ve öğretmek caiz midir? • Sihirbazın hükmü",
      "Nesih (Hükümlerin Kaldırılması) • Kur’an’da nesih meselesi • Sebeb-i nüzul ve kıraat farklılıkları • İlahi şeriatlarda nesih mümkün mü? • Nesih çeşitleri • Kur’an’ın sünnetle neshi meselesi • Nesihte hikmet",
      "Kıble ve İbadetlerde Yön • Kıblenin değiştirilmesi (Sebeb-i nüzul) • Kıraat ve i‘rab yönleri • Mescid-i Haram’ın anlamı • Kâbe’nin aynına mı yoksa yönüne mi dönülmeli? • Kâbe’nin üstünde namaz kılmak meselesi",
      "Hac ve Umre İbadetleri • Safa ile Merve arasında sa‘y • Hac ve umreyi tamamlama emri • İhram, haccın şartları ve engelleri • Hedy (kurban) ve hükümleri • Umrenin hükmü",
      "Oruç ve Ramazan • Oruç farziyeti (Sebeb-i nüzul) • Hastalık ve yolculukta oruç • İmsak ve iftar meseleleri • Hamile ve emzikli kadınların durumu • İtikâf ve hükümleri",
      "Aile Hukuku ve Toplumsal Düzen • Nikâh ve çok eşlilik • Kadınların iddeti ve boşanma hükümleri • Nafaka ve mehir • Aile içi anlaşmazlıkların çözümü • Yetim mallarının korunması",
      "• Sûre-i Nûr’a giriş • Zina ile ilgili hükümler: o Şartları, şahitlik meselesi o Had cezaları o İnkâr eden fırkalar ve cevaplar • Tartışma: Hudûd cezalarının hikmeti",
      "İftira ve Karı-Koca Arası Yeminleşme • iftira atmanın hükmü ve şartları • Şahitlik ve cezalar o Ne zaman gerekir? o Usulü ve sonuçları o Çocuğun nesebi meselesi",
      "İftira hadisesi ve Aile Hukuku • İfk hadisesi ve ibretler • Büyük günahların amele etkisi • Nikâh meseleleri: o Zina edenle evlilik o Kadının nikâh akdinde rolü o Zorla evlendirme meselesi",
      "• Ev adabı: selam, izin isteme, tekrar etme • Mahremiyet ve özel hayatın korunması • Hicab ayetleri: o Kadın ve erkeğin avreti o Zînetin gösterilmesi sınırları o Yabancıya bakış ve sınırlar",
      "Evlenme ve Aile Nikâhın teşviki ve fuhşun yasaklanması Evlilikte hak ve sorumluluklar • Kölelik ve nikâh • Nafaka, mehir, boşanma öncesi hükümler",
      "Boşanma ve Hükümleri • Talâkın çeşitleri: • Talâk öncesi ve sonrası hükümler • İddet süreleri • Nafaka ve barınma hakkı • dönüş ve şahitlik",
      "• Görgü ve sosyal ilişkiler: o misafirlik, düğün yemeği • Kadın-erkek ilişkilerinde sınırlar • Güncel meseleler: o Fotoğraf ve tasvir meselesi o İslam’da savaş ve barış ilkeleri",
      "Ahkam ayetleri: kapsam ve temel kavramlar"
    ],
