    "term": "Bahar",
    "instructor": "Dr. Öğr. Üyesi ESRA HERGÜNER",
    "purpose": "İslam düşüncesinde nübüvvet ve siyaset teorilerinin kelâmî temellerini incelemek; nübüvvet, imamet, hilafet ve siyasal meşruiyet kavramlarını klasik ve modern yaklaşımlar çerçevesinde değerlendirmek; öğrencilerin ilgili kaynakları analiz ederek nübüvvet-siyaset ilişkisine dair eleştirel bakış açısı geliştirmelerini sağlamaktır.",
    "content": "Bu ders, İslam düşüncesinde nübüvvet ve siyaset teorilerinin kelâmî temellerini ele alır. Nübüvvetin mahiyeti, gerekliliği ve epistemolojik yönü ile imamet, hilafet ve siyasal meşruiyet kavramları klasik ve modern yaklaşımlar çerçevesinde incelenir. Mu‘tezile, Eş‘arî, Mâtürîdî ve Şiî kelâm gelenekleri karşılaştırmalı olarak değerlendirilir. Farabî, Mâverdî, Gazzâlî, İbn Teymiyye ve İbn Haldûn’un siyaset teorileri üzerinden nübüvvet-siyaset ilişkisi analiz edilir. Modern dönemdeki yorumlar ve güncel tartışmalar da ele alınarak öğrencilerin eleştirel bakış geliştirmesi hedeflenir.",
    "methods": "Anlatım Soru-CevapTartışma",
    "resources": "Dersin gerçek OBS kaynakları; birincil ve ikincil temel_islam_bilimleri kaynakları, güncel temel_islam_bilimleri literatürü, arşiv ve kütüphane katalogları ile hakemli makaleler.",
